function n(e){if(!e)return null;let t=String(e).trim();if(/^\d{4}-\d{2}-\d{2}$/.test(t))return new Date(t+"T00:00:00");/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}/.test(t)&&(t=t.replace(" ","T")),/[zZ]|[+-]\d{2}:\d{2}$/.test(t)||(t+="Z");const r=new Date(t);return isNaN(r.getTime())?null:r}function a(e){const t=n(e);if(!t)return"";const r=Math.round((Date.now()-t.getTime())/1e3);if(r<60)return"just now";if(r<3600)return`${Math.floor(r/60)}m ago`;if(r<86400)return`${Math.floor(r/3600)}h ago`;const o=Math.floor(r/86400);return o<30?`${o}d ago`:o<365?`${Math.floor(o/30)}mo ago`:`${Math.floor(o/365)}y ago`}function i(e){return e?e.replace(/_/g," ").replace(/\b\w/g,t=>t.toUpperCase()):""}function s(e){const t=Math.max(0,Math.round(Number(e||0))),r=Math.floor(t/60),o=t%60;return`${r}:${o.toString().padStart(2,"0")}`}function u(e){const t=Math.max(0,Number(e||0)),r=Math.floor(t/60),o=t-r*60;return`${r}:${o.toFixed(3).padStart(6,"0")}`}export{i as a,s as d,a as r,u as t};
